/** Intl-backed month-grid helpers shared by Calendar and DatePicker. All math is UTC to stay DST-proof. */

export interface MonthGridDay {
  iso: string
  day: number
  inMonth: boolean
}

export function parseIsoDate(value: string): { year: number; month: number; day: number } | null {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value)
  if (!match) return null
  const year = Number(match[1])
  const month = Number(match[2]) - 1
  const day = Number(match[3])
  if (month < 0 || month > 11 || day < 1 || day > 31) return null
  return { year, month, day }
}

export function toIsoDate(year: number, month: number, day: number): string {
  return `${year}-${String(month + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`
}

export function firstDayOfWeek(locale: string): number {
  try {
    const info = new Intl.Locale(locale) as Intl.Locale & {
      weekInfo?: { firstDay: number }
      getWeekInfo?: () => { firstDay: number }
    }
    return info.getWeekInfo?.().firstDay ?? info.weekInfo?.firstDay ?? 1
  } catch {
    return 1
  }
}

/** Returns 6 fixed weeks x 7 days covering the month; days outside the month are included for grid stability. */
export function buildMonthGrid(year: number, month: number, weekStartsOn: number): MonthGridDay[][] {
  const startDay = weekStartsOn % 7
  const firstWeekday = new Date(Date.UTC(year, month, 1, 12)).getUTCDay()
  const back = (firstWeekday - startDay + 7) % 7
  const start = new Date(Date.UTC(year, month, 1 - back, 12))
  const weeks: MonthGridDay[][] = []
  for (let week = 0; week < 6; week += 1) {
    const row: MonthGridDay[] = []
    for (let weekday = 0; weekday < 7; weekday += 1) {
      const cell = new Date(start.getTime() + (week * 7 + weekday) * 86_400_000)
      row.push({
        iso: toIsoDate(cell.getUTCFullYear(), cell.getUTCMonth(), cell.getUTCDate()),
        day: cell.getUTCDate(),
        inMonth: cell.getUTCMonth() === month,
      })
    }
    weeks.push(row)
  }
  return weeks
}

export function monthLabel(year: number, month: number, locale: string): string {
  return new Intl.DateTimeFormat(locale, { month: 'long', year: 'numeric', timeZone: 'UTC' }).format(
    new Date(Date.UTC(year, month, 1, 12)),
  )
}

export function weekdayNames(locale: string, weekStartsOn: number): string[] {
  const formatter = new Intl.DateTimeFormat(locale, { weekday: 'short', timeZone: 'UTC' })
  const sunday = Date.UTC(2023, 9, 1, 12)
  const names = Array.from({ length: 7 }, (_, index) => formatter.format(new Date(sunday + index * 86_400_000)))
  const rotate = weekStartsOn % 7
  return names.slice(rotate).concat(names.slice(0, rotate))
}

export function formatDateDisplay(iso: string, locale: string): string {
  const parsed = parseIsoDate(iso)
  if (!parsed) return iso
  return new Intl.DateTimeFormat(locale, { dateStyle: 'medium', timeZone: 'UTC' }).format(
    new Date(Date.UTC(parsed.year, parsed.month, parsed.day, 12)),
  )
}

.cu-calendar {
  display: inline-block;
  padding-block: var(--cu-space-2);
  padding-inline: var(--cu-space-2);
  border: 1px solid var(--cu-color-border-default);
  border-radius: var(--cu-radius-md);
  background: var(--cu-color-background-default);
  color: var(--cu-color-fg-default);
}

.cu-calendar__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--cu-space-2);
  margin-block-end: var(--cu-space-2);
}

.cu-calendar__headline {
  font-weight: 700;
}

.cu-calendar__nav {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-inline-size: var(--cu-touch-target-min);
  min-block-size: var(--cu-touch-target-min);
  border: 0;
  border-radius: var(--cu-radius-sm);
  background: transparent;
  color: inherit;
  font: inherit;
  cursor: pointer;
}

.cu-calendar__nav:focus-visible {
  outline: 3px solid var(--cu-color-palette-brand);
}

.cu-calendar__weekdays,
.cu-calendar__week {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
}

.cu-calendar__weekday {
  padding-block: var(--cu-space-1);
  text-align: center;
  font-size: 0.82rem;
  font-weight: 700;
  color: color-mix(in srgb, var(--cu-color-fg-default) 72%, transparent);
}

.cu-calendar__cell,
.cu-calendar__blank {
  display: flex;
  align-items: center;
  justify-content: center;
}

.cu-calendar__day {
  min-inline-size: var(--cu-touch-target-min);
  min-block-size: var(--cu-touch-target-min);
  border: 0;
  border-radius: var(--cu-radius-sm);
  background: transparent;
  color: inherit;
  font: inherit;
  cursor: pointer;
}

.cu-calendar__day:hover {
  background: color-mix(in srgb, var(--cu-color-palette-brand) 10%, var(--cu-color-background-default));
}

.cu-calendar__day[aria-selected='true'] {
  background: var(--cu-color-palette-brand);
  color: var(--cu-color-fg-inverse);
}

.cu-calendar__day:focus-visible {
  outline: 3px solid var(--cu-color-palette-brand);
}
